#!/bin/bash
# Uninstall script for Any.do
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Any.do..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Any.do if running..."
pkill -f "Any.do" 2>/dev/null || true

# Remove /Applications/Anydo.app
echo "Removing /Applications/Anydo.app..."
if [ -d "/Applications/Anydo.app" ]; then
    rm -rf "/Applications/Anydo.app" 2>/dev/null || true
elif [ -f "/Applications/Anydo.app" ]; then
    rm -f "/Applications/Anydo.app" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/@anydo
echo "Removing $HOME/Library/Application Support/@anydo..."
if [ -d "$HOME/Library/Application Support/@anydo" ]; then
    rm -rf "$HOME/Library/Application Support/@anydo" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/@anydo" ]; then
    rm -f "$HOME/Library/Application Support/@anydo" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/com.anydo.mac.plist
echo "Removing $HOME/Library/Preferences/com.anydo.mac.plist..."
if [ -d "$HOME/Library/Preferences/com.anydo.mac.plist" ]; then
    rm -rf "$HOME/Library/Preferences/com.anydo.mac.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/com.anydo.mac.plist" ]; then
    rm -f "$HOME/Library/Preferences/com.anydo.mac.plist" 2>/dev/null || true
fi

# Remove $HOME/Library/Saved Application State/com.anydo.mac.savedState
echo "Removing $HOME/Library/Saved Application State/com.anydo.mac.savedState..."
